"""Emit the closed persistent method selections from their existing parameter authority."""

from __future__ import annotations

from typing import Any

from parameter_structs import TYPES, parameter_field

PREAMBLE = (
    "// SPDX-FileCopyrightText: 2026 Ervins Strauhmanis\n"
    "// SPDX-License-Identifier: MPL-2.0\n"
    "// Generated by tools/generate_spec.py from spec/method-contract.json.\n"
    "#pragma once\n"
)


def request_types(families: list[dict[str, Any]], options: list[dict[str, Any]]) -> tuple[str, str]:
    """Separate data and descriptors solely to keep each generated owner below the size guard."""
    by_name = {option["name"]: option for option in options}
    data = PREAMBLE
    for header in (
        "binarization",
        "contrast",
        "denoising",
        "illumination",
        "restoration",
        "sharpening",
    ):
        data += f'#include "docenhance/methods/{header}.hpp"\n'
    data += '#include "docenhance/methods/parameters.hpp"\nnamespace docenhance::record {\n'
    fields = PREAMBLE + (
        '#include "docenhance/core/fields.hpp"\n'
        '#include "docenhance/methods/parameter_fields.hpp"\n'
        '#include "docenhance/record/method_requests.hpp"\n'
        "#include <array>\n#include <string_view>\n#include <tuple>\n#include <utility>\n"
        "namespace docenhance {\n"
    )
    for family in families:
        for method in family["methods"]:
            raw = TYPES[method["id"]]
            name = raw.removesuffix("Parameters")
            selection = name + "Request"
            members = [*family["shared"], *method["parameters"]]
            own = [by_name[member["option"]] for member in members]
            data += selection_data(selection, name, raw, own)
            data += selection_validation(selection, name, own)
            fields += selection_fields(selection, name, own)
    return data + "} // namespace docenhance::record\n", fields + "} // namespace docenhance\n"


def selection_data(selection: str, method: str, raw: str, own: list[dict[str, Any]]) -> str:
    """Surface's selector is outside its numeric parameters in the normative v15 shape."""
    text = f"struct {selection} {{\n"
    if method == "Surface":
        text += "    struct Parameters {\n"
        for option in own:
            field = option["field"]
            text += (
                f"        decltype(methods::{raw}{{}}.{field}) {field} = "
                f"methods::{raw}{{}}.{field};\n"
            )
        text += "        bool operator==(const Parameters&) const = default;\n    };\n"
        selector = "methods::SurfaceMode"
        default = selector + "::explicit_surface"
        parameters = "Parameters"
    else:
        text += "    enum class Selector { selected };\n"
        selector, default, parameters = "Selector", "Selector::selected", f"methods::{raw}"
    text += f"    unsigned version = methods::{method}::descriptor().method_version;\n"
    text += f"    {selector} selector = {default};\n    {parameters} parameters;\n"
    return text + f"    bool operator==(const {selection}&) const = default;\n}};\n"


def selection_validation(selection: str, method: str, own: list[dict[str, Any]]) -> str:
    """Delegate numerical admission to the actual factory, not another parameter rule table."""
    text = f"[[nodiscard]] inline bool validate(const {selection}& value) {{\n"
    text += f"    if (value.version != methods::{method}::descriptor().method_version"
    if method != "Surface":
        text += f" || value.selector != {selection}::Selector::selected"
    text += ") { return false; }\n"
    if method == "Surface":
        text += "    const methods::SurfaceParameters parameters{.mode = value.selector,\n"
        text += "".join(
            f"        .{option['field']} = value.parameters.{option['field']},\n" for option in own
        )
        text += "    };\n    return methods::Surface::create(parameters).has_value();\n"
    elif method == "Otsu":
        text += "    return methods::valid_parameters(value.parameters);\n"
    else:
        parameter = (
            "value.parameters.threshold" if method == "FixedThreshold" else "value.parameters"
        )
        text += f"    return methods::{method}::create({parameter}).has_value();\n"
    return text + "}\n"


def selection_fields(selection: str, method: str, own: list[dict[str, Any]]) -> str:
    """One method tag, exact current version, one selector and one parameters object."""
    owner = f"record::{selection}"
    text = ""
    if method == "Surface":
        text += f"template <> struct core::Fields<{owner}::Parameters> {{\n"
        text += (
            f"    using Value = {owner}::Parameters;\n"
            "    static constexpr auto list = std::tuple{\n"
        )
        text += "".join(parameter_field(option) for option in own)
        text += "    };\n};\n"
    else:
        text += f"template <> struct core::EnumNames<{owner}::Selector> {{\n"
        text += (
            f"    static constexpr std::array list{{std::pair{{{owner}::Selector::selected, "
            f"methods::{method}::descriptor().selector}},}};\n}};\n"
        )
    text += f"template <> struct core::WireTag<{owner}> {{\n"
    text += (
        '    static constexpr std::string_view key = "method";\n'
        f"    static constexpr auto value = methods::{method}::descriptor().id;\n}};\n"
    )
    text += f"template <> struct core::Fields<{owner}> {{\n    using Value = {owner};\n"
    text += "    static constexpr auto list = std::tuple{\n"
    text += (
        '        core::field("version", &Value::version, '
        f"core::Exact{{methods::{method}::descriptor().method_version}}),\n"
    )
    text += (
        '        core::field("selector", &Value::selector),\n'
        '        core::field("parameters", &Value::parameters),\n'
    )
    return text + "    };\n};\n"
